    const lat = Math.atan(Math.sinh(Math.PI * (1 - 2 * (ty + ly / extent) / n)))
      * 180 / Math.PI;
    const p = map.latLngToContainerPoint([lat, lon]);
    return [p.x, p.y];
  };
}

