function makeTileXformFast(project, tile) {
  const n = 2 ** tile.z, ext = tile.extent || 4096;
  const lonW = tile.tx / n * 360 - 180, lonE = (tile.tx + 1) / n * 360 - 180;
  const latN = tileLat(tile.ty, n), latS = tileLat(tile.ty + 1, n);
  const pNW = project(lonW, latN), pSE = project(lonE, latS);
  const sx = (pSE[0] - pNW[0]) / ext, sy = (pSE[1] - pNW[1]) / ext;
  return (lx, ly) => [pNW[0] + lx * sx, pNW[1] + ly * sy];
}
