function tileLat(y, n) {
  return Math.atan(Math.sinh(Math.PI * (1 - 2 * y / n))) * 180 / Math.PI;
}

function makeTileXform(project, tile) {
  const n = 2 ** tile.z;
  const ext = tile.extent || 4096;
  const west = tile.tx / n * 360 - 180;
  const east = (tile.tx + 1) / n * 360 - 180;
  const north = tileLat(tile.ty, n);
  const south = tileLat(tile.ty + 1, n);
  const p0 = project(west, north);
  const p1 = project(east, south);
  const sx = (p1[0] - p0[0]) / ext;
  const sy = (p1[1] - p0[1]) / ext;
  return (lx, ly) => [p0[0] + lx * sx, p0[1] + ly * sy];
}
```

