{"content": "// 极简 CDP 驱动：启动 headless chrome、开页、等条件、执行 JS、截图。
// 用法：node cdp.mjs <url> <out.png> [--wait=<js expr>] [--eval=<js expr>] [--w=1440] [--h=900]
import { spawn } from "node:child_process";
import { writeFileSync } from "node:fs";

const args = process.argv.slice(2);
const url = args[0];
const out = args[1];
const opt = {};
for (const a of args.slice(2)) {
  const m = a.match(/^--([a-z]+)=(.*)$/);
  if (m) opt[m[1]] = m[2];
}
const W = Number(opt.w || 1440);
const H = Number(opt.h || 900);
const PORT = 9333 + Math.floor(Math.random() * 400);

const CH = "/home/jinsc/.cache/ms-playwright/chromium_headless_shell-1228/chrome-headless-shell-linux64/chrome-headless-shell";
const proc = spawn(CH, [
  "--headless", "--disable-gpu", "--no-sandbox", "--hide-scrollbars",
  `--window-size=${W},${H}`, `--remote-debugging-port=${PORT}`,
  "--user-data-dir=/tmp/cdp-profile-" + PORT,
  "about:blank",
], { stdio: ["ignore", "ignore", "pipe"] });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function targets() {
  for (let i = 0; i < 60; i++) {
    try {
      const r = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const list = await r.json();
      const page = list.find((t) => t.type === "page");
      if (page) return page;
    } catch (e) { /* not up yet */ }
    await sleep(100);
  }
  throw new Error("chrome did not start");
}

const page = await targets();
const ws = new WebSocket(page.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
const events = [];
ws.addEventListener("message", (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  } else if (msg.method) {
    events.push(msg);
  }
});
await new Promise((r) => ws.addEventListener("open", r, { once: true }));

function send(method, params = {}) {
  const mid = ++id;
  return new Promise((resolve, reject) => {
    pending.set(mid, { resolve, reject });
    ws.send(JSON.stringify({ id: mid, method, params }));
  });
}

await send("Page.enable");
await send("Runtime.enable");
await send("Log.enable");
await send("Emulation.setDeviceMetricsOverride", {
  width: W, height: H, deviceScaleFactor: 1, mobile: false,
});
await send("Page.navigate", { url });

async function evaluate(expr) {
  const r = await send("Runtime.evaluate", {
    expression: expr, returnByValue: true, awaitPromise: true,
  });
  if (r.exceptionDetails) {
    return { error: r.exceptionDetails.text + " " + (r.exceptionDetails.exception?.description || "") };
  }
  return { value: r.result.value };
}

const waitExpr = opt.wait;
if (waitExpr) {
  for (let i = 0; i < 120; i++) {
    const r = await evaluate(waitExpr);
    if (r.value) break;
    await sleep(100);
  }
}
await sleep(Number(opt.settle || 900));

if (opt.eval) {
  const r = await evaluate(opt.eval);
  console.log("eval:", JSON.stringify(r));
  await sleep(Number(opt.after || 400));
}

if (opt.shot2) {
  const r2 = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: false });
  writeFileSync(opt.shot2, Buffer.from(r2.data, "base64"));
}

const shot = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: false });
writeFileSync(out, Buffer.from(shot.data, "base64"));

const logs = events
  .filter((e) => e.method === "Runtime.consoleAPICalled" || e.method === "Runtime.exceptionThrown")
  .map((e) => e.method === "Runtime.exceptionThrown"
    ? "EXC " + (e.params.exceptionDetails?.exception?.description || e.params.exceptionDetails?.text)
    : "LOG " + e.params.args.map((a) => a.value ?? a.description ?? a.type).join(" "))
  .slice(-30);
if (logs.length) console.log(logs.join("\n"));

ws.close();
proc.kill("SIGKILL");
process.exit(0);
