                uint32_t key = xkey_to_lv(ks);

                if (key) {
                    key_push(key);
                }
                break;
            }
            case ClientMessage:
                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
                    s.quit = true;
                }
                break;
            case DestroyNotify:
                s.quit = true;
                break;
