 * @file vmap_raster.h
 * @brief 极简 RGB565 光栅化（矩形 / 多边形 / 粗线 / 圆）。
 *
 * 这个文件是**给 MCU 端 vmap 做参考实现**用的：不依赖 LVGL 的 draw 层，
 * 直接往 canvas 的 RGB565 缓冲里写像素 —— 和板子上 vmap_render.c 的路子
 * 一样。模拟器里先用它画 mock 地图，验证调色板、线宽、字号在 1× 下的观感。
 */

#ifndef VMAP_RASTER_H
#define VMAP_RASTER_H

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define VR_RGB565(r, g, b) \
    ((uint16_t)(((((uint16_t)(r)) & 0xF8u) << 8) | \
                ((((uint16_t)(g)) & 0xFCu) << 3) | \
                (((uint16_t)(b)) >> 3)))

typedef struct {
    uint16_t *px;
    int w;
