{"content": "/**
 * @file vmap_raster.c
 * @brief 极简 RGB565 光栅化实现（扫描线多边形 + 四边形粗线 + 圆帽）。
 */

#include <math.h>
#include <string.h>

#include "vmap_raster.h"

static inline void put_px(vr_canvas_t *c, int x, int y, uint16_t color)
{
    if (x < 0 || y < 0 || x >= c->w || y >= c->h) {
        return;
    }
    c->px[(size_t)y * (size_t)c->w + (size_t)x] = color;
}

void vr_fill(vr_canvas_t *c, uint16_t color)
{
    if (!c || !c->px) {
        return;
    }
    for (size_t i = 0; i < (size_t)c->w * (size_t)c->h; i++) {
        c->px[i] = color;
    }
}

void vr_rect(vr_canvas_t *c, int x0, int y0, int x1, int y1, uint16_t color)
{
    if (!c || !c->px) {
        return;
    }
    if (x0 > x1) {
        int t = x0;
        x0 = x1;
        x1 = t;
    }
    if (y0 > y1) {
        int t = y0;
        y0 = y1;
        y1 = t;
    }
    if (x0 < 0) x0 = 0;
    if (y0 < 0) y0 = 0;
    if (x1 > c->w - 1) x1 = c->w - 1;
    if (y1 > c->h - 1) y1 = c->h - 1;
    for (int y = y0; y <= y1; y++) {
        uint16_t *row = c->px + (size_t)y * (size_t)c->w;
        for (int x = x0; x <= x1; x++) {
            row[x] = color;
        }
    }
}

/* 扫描线填充：采样线取 y+0.5（用 2 倍坐标做整数运算）。 */
void vr_poly(vr_canvas_t *c, const int32_t *xy, int n, uint16_t color)
{
    if (!c || !c->px || !xy || n < 3) {
        return;
    }

    int32_t miny = xy[1];
    int32_t maxy = xy[1];
    for (int i = 1; i < n; i++) {
        if (xy[2 * i + 1] < miny) miny = xy[2 * i + 1];
        if (xy[2 * i + 1] > maxy) maxy = xy[2 * i + 1];
    }
    if (miny < 0) miny = 0;
    if (maxy > c->h - 1) maxy = c->h - 1;

    int32_t xs[128];
    for (int32_t y = miny; y <= maxy; y++) {
        const int32_t sy = y * 2 + 1;
        int nx = 0;

        for (int i = 0; i < n; i++) {
            const int32_t ax = xy[2 * i];
            const int32_t ay = xy[2 * i + 1] * 2;
            const int32_t bx = xy[2 * ((i + 1) % n)];
            const int32_t by = xy[2 * ((i + 1) % n) + 1] * 2;

            if ((ay <= sy && by > sy) || (by <= sy && ay > sy)) {
                const int32_t t = sy - ay;
                const int32_t x = ax + (int32_t)(((int64_t)(bx - ax) * t) / (by - ay));
                if (nx < (int)(sizeof(xs) / sizeof(xs[0]))) {
                    xs[nx++] = x;
                }
            }
        }
        if (nx < 2) {
            continue;
        }
        /* 插入排序：交点一般只有几个 */
        for (int i = 1; i < nx; i++) {
            int32_t v = xs[i];
            int j = i - 1;
            while (j >= 0 && xs[j] > v) {
                xs[j + 1] = xs[j];
                j--;
            }
            xs[j + 1] = v;
        }
        uint16_t *row = c->px + (size_t)y * (size_t)c->w;
        for (int i = 0; i + 1 < nx; i += 2) {
            int32_t x0 = xs[i];
            int32_t x1 = xs[i + 1];
            if (x0 < 0) x0 = 0;
            if (x1 > c->w - 1) x1 = c->w - 1;
            for (int32_t x = x0; x <= x1; x++) {
                row[x] = color;
            }
        }
    }
}

void vr_disc(vr_canvas_t *c, int cx, int cy, int r, uint16_t color)
{
    if (r <= 0) {
        put_px(c, cx, cy, color);
        return;
    }
    for (int dy = -r; dy <= r; dy++) {
        const int dx = (int)(sqrt((double)(r * r - dy * dy)) + 0.5);
        int y = cy + dy;
        if (y < 0 || y >= c->h) {
            continue;
        }
        uint16_t *row = c->px + (size_t)y * (size_t)c->w;
        int x0 = cx - dx;
        int x1 = cx + dx;
        if (x0 < 0) x0 = 0;
        if (x1 > c->w - 1) x1 = c->w - 1;
        for (int x = x0; x <= x1; x++) {
            row[x] = color;
        }
    }
}

/* 粗线：每段用"沿线方向的矩形（四边形）"填，拐点补圆帽 —— 和设备端
 * stroke_ribbon 的思路一致（设备是逐段扫描线 + 端点圆帽）。 */
void vr_line(vr_canvas_t *c, const int32_t *xy, int n, int width, uint16_t color)
{
    if (!c || !c->px || !xy || n < 2) {
        return;
    }
    if (width < 1) {
        width = 1;
    }
    const double half = (double)width * 0.5;

    for (int i = 0; i + 1 < n; i++) {
        const double ax = (double)xy[2 * i];
        const double ay = (double)xy[2 * i + 1];
        const double bx = (double)xy[2 * i + 2];
        const double by = (double)xy[2 * i + 3];
        const double dx = bx - ax;
        const double dy = by - ay;
        const double len = sqrt(dx * dx + dy * dy);
        if (len < 0.01) {
            continue;
        }
        const double nx = -dy / len * half;
        const double ny = dx / len * half;

        int32_t quad[8];
        quad[0] = (int32_t)lround(ax + nx);
        quad[1] = (int32_t)lround(ay + ny);
        quad[2] = (int32_t)lround(bx + nx);
        quad[3] = (int32_t)lround(by + ny);
        quad[4] = (int32_t)lround(bx - nx);
        quad[5] = (int32_t)lround(by - ny);
        quad[6] = (int32_t)lround(ax - nx);
        quad[7] = (int32_t)lround(ay - ny);
        vr_poly(c, quad, 4, color);
    }

    /* 圆帽/圆角：宽度 >2 才有意义 */
    if (width >= 3) {
        const int r = width / 2;
        for (int i = 0; i < n; i++) {
            vr_disc(c, xy[2 * i], xy[2 * i + 1], r, color);
        }
    }
}
