{"content": "/**
 * @file scene_vmap.c
 * @brief vmap 底图 mock：直接用 RGB565 光栅化 + LVGL 画字。
 *
 * 这不是最终渲染器，而是"调色板/线宽/字号在 1× 下到底好不好看"的试验台：
 * 几何用 vmap_raster.c（和板端 vmap_render.c 同路子：扫描线填充 + 四边形粗线），
 * 文字走 lv_canvas 的 draw layer（板端 vmap_label.c 也是往同一块 canvas 上画）。
 *
 * 调色板数值和 HTML 预览的 paper 预设一一对应，两边改要一起改。
 */

#include <string.h>

#include "sim.h"
#include "vmap_raster.h"

/* ── 调色板（= vmap_style.js 的 paper 预设） ─────────────────────── */
#define C_BG        0xF5F3EC
#define C_PARK      0xD9E9CB
#define C_FOREST    0xCBE0BC
#define C_WATER     0xA9D0E8
#define C_WATER_EDGE 0x83BBD8
#define C_CASE_MAJ  0xCCA85C
#define C_FILL_MAJ  0xFBDC9C
#define C_CASE_MID  0xB7B1A4
#define C_FILL_MID  0xFEFDF9
#define C_CASE_MIN  0xCBC5B8
#define C_PATH      0xB0824F
#define C_TRACK     0xE0503A
#define C_LBL_ROAD  0x514C45
#define C_LBL_WATER 0x3D7EA6
#define C_LBL_PARK  0x3F7048

static uint16_t *s_buf;

static inline uint16_t hex565(uint32_t rgb)
{
    return vr_rgb565((uint8_t)(rgb >> 16), (uint8_t)(rgb >> 8), (uint8_t)rgb);
}

static void dashed_line(vr_canvas_t *c, const int32_t *xy, int n, int width,
                        uint16_t color, int on, int off)
{
    const int period = on + off;
    int phase = 0;

    for (int i = 0; i + 1 < n; i++) {
        const int32_t ax = xy[2 * i];
        const int32_t ay = xy[2 * i + 1];
        const int32_t bx = xy[2 * i + 2];
        const int32_t by = xy[2 * i + 3];
        const int dx = bx - ax;
        const int dy = by - ay;
        const int len = (int)(0.5 + sqrt((double)(dx * dx + dy * dy)));

        for (int t = 0; t < len; t++) {
            if (phase % period >= on) {
                phase++;
                continue;
            }
            const int x0 = ax + dx * t / (len ? len : 1);
            const int y0 = ay + dy * t / (len ? len : 1);
            const int x1 = ax + dx * (t + 1) / (len ? len : 1);
            const int y1 = ay + dy * (t + 1) / (len ? len : 1);
            int32_t seg[4] = { x0, y0, x1, y1 };

            vr_line(c, seg, 2, width, color);
            phase++;
        }
    }
}

static void canvas_label(lv_obj_t *canvas, lv_layer_t *layer, int x, int y, int w,
                         const char *txt, uint32_t color, int px, bool italic,
                         bool centered)
{
    lv_draw_label_dsc_t dsc;

    lv_draw_label_dsc_init(&dsc);
    dsc.text = txt;
    dsc.font = sim_font_cjk(px);
    dsc.color = lv_color_hex(color);
    dsc.align = centered ? LV_TEXT_ALIGN_CENTER : LV_TEXT_ALIGN_LEFT;
    dsc.letter_space = 0;
    /* 白描边：地图文字必须有 halo，否则压在路/水上读不出来 */
    dsc.outline_stroke_color = lv_color_hex(0xFFFFFF);
    dsc.outline_stroke_width = 3;
    dsc.outline_stroke_opa = LV_OPA_90;
    (void)italic;

    lv_area_t a;
    a.x1 = x;
    a.y1 = y;
    a.x2 = x + w - 1;
    a.y2 = y + px * 2;
    lv_draw_label(layer, &dsc, &a);
}

void scene_vmap_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    const int W = cfg->width;
    const int H = cfg->height;

    lv_obj_set_style_bg_color(scr, lv_color_hex(C_BG), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    s_buf = lv_malloc((size_t)W * (size_t)H * 2u);
    if (!s_buf) {
        return;
    }

    lv_obj_t *canvas = lv_canvas_create(scr);
    lv_obj_set_pos(canvas, 0, 0);
    lv_canvas_set_buffer(canvas, s_buf, W, H, LV_COLOR_FORMAT_RGB565);

    vr_canvas_t c = { .px = s_buf, .w = W, .h = H };

    /* 1) 底色 + 绿地 */
    vr_fill(&c, hex565(C_BG));

    int32_t forest[] = { 0, 300, 90, 268, 132, 300, 96, 400, 0, 400 };
    vr_poly(&c, forest, 5, hex565(C_FOREST));

    int32_t park[] = { 150, 250, 232, 268, 240, 340, 168, 352, 140, 300 };
    vr_poly(&c, park, 5, hex565(C_PARK));

    /* 2) 水面：填色 + 一圈稍深的边 */
    int32_t lake[] = { 138, 26, 196, 18, 226, 52, 214, 96, 166, 104, 140, 70 };
    vr_poly(&c, lake, 6, hex565(C_WATER));
    {
        int32_t edge[14];
        memcpy(edge, lake, sizeof(lake));
        edge[12] = lake[0];
        edge[13] = lake[1];
        vr_line(&c, edge, 7, 1, hex565(C_WATER_EDGE));
    }

    /* 3) 支路网格：白芯 + 浅灰壳 */
    static const int32_t grid[][4] = {
        { 0, 150, 240, 158 }, { 0, 236, 240, 244 },
        { 52, 0, 58, 400 },   { 104, 0, 110, 400 },
        { 186, 0, 192, 400 }, { 228, 0, 232, 400 },
    };
    for (size_t i = 0; i < sizeof(grid) / sizeof(grid[0]); i++) {
        vr_line(&c, grid[i], 2, 4, hex565(C_CASE_MIN));
    }
    for (size_t i = 0; i < sizeof(grid) / sizeof(grid[0]); i++) {
        vr_line(&c, grid[i], 2, 2, hex565(C_FILL_MID));
    }

    /* 4) 次干道（横向） */
    int32_t mid[] = { 0, 196, 240, 204 };
    vr_line(&c, mid, 2, 5, hex565(C_CASE_MID));
    vr_line(&c, mid, 2, 3, hex565(C_FILL_MID));

    /* 5) 主干道（斜穿） */
    int32_t major[] = { -10, 372, 70, 330, 150, 292, 250, 250 };
    vr_line(&c, major, 4, 7, hex565(C_CASE_MAJ));
    vr_line(&c, major, 4, 4, hex565(C_FILL_MAJ));

    /* 6) 步道（虚线） */
    int32_t path[] = { 24, 60, 60, 140, 96, 208, 128, 286 };
    dashed_line(&c, path, 4, 2, hex565(C_PATH), 5, 4);

    /* 7) 骑行轨迹 + 当前位置 */
    int32_t track[] = { 30, 340, 62, 300, 96, 262, 118, 214, 150, 186, 190, 168 };
    vr_line(&c, track, 6, 5, hex565(0xFFFFFF));
    vr_line(&c, track, 6, 3, hex565(C_TRACK));
    vr_disc(&c, 190, 168, 6, hex565(0xFFFFFF));
    vr_disc(&c, 190, 168, 4, hex565(0x1D6FD0));

    /* 8) 文字：和板端一样画在同一块 canvas 上 */
    lv_layer_t layer;
    lv_canvas_init_layer(canvas, &layer);
    canvas_label(canvas, &layer, 84, 176, 72, "清流路", C_LBL_ROAD, 11, false, true);
    canvas_label(canvas, &layer, 160, 44, 64, "东升湖", C_LBL_WATER, 11, true, true);
    canvas_label(canvas, &layer, 160, 300, 72, "中央公园", C_LBL_PARK, 11, false, true);
    canvas_label(canvas, &layer, 44, 300, 64, "扬子大道", C_LBL_ROAD, 10, false, false);
    lv_canvas_finish_layer(canvas, &layer);

    /* 9) 角标：说明这块是什么（真机上不会有） */
    lv_obj_t *badge = lv_label_create(scr);
    lv_label_set_text(badge, "vmap mock · z14 · 1x");
    lv_obj_set_style_text_font(badge, &lv_font_montserrat_12, 0);
    lv_obj_set_style_text_color(badge, lv_color_hex(0x6B675E), 0);
    lv_obj_set_style_bg_color(badge, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_bg_opa(badge, LV_OPA_70, 0);
    lv_obj_set_style_pad_hor(badge, 6, 0);
    lv_obj_set_style_pad_ver(badge, 3, 0);
    lv_obj_set_style_radius(badge, 6, 0);
    lv_obj_align(badge, LV_ALIGN_TOP_LEFT, 6, 6);
}
