        const int32_t bx = xy[2 * i + 2];
        const int32_t by = xy[2 * i + 3];
        const int dx = bx - ax;
        const int dy = by - ay;
        const int len = (int)(0.5 + sqrt((double)(dx * dx + dy * dy)));

        for (int t = 0; t < len; t++) {
            if (phase % period >= on) {
                phase++;
                continue;
            }
            const int x0 = ax + dx * t / (len ? len : 1);
            const int y0 = ay + dy * t / (len ? len : 1);
            const int x1 = ax + dx * (t + 1) / (len ? len : 1);
            const int y1 = ay + dy * (t + 1) / (len ? len : 1);
            int32_t seg[4] = { x0, y0, x1, y1 };

            vr_line(c, seg, 2, width, color);
            phase++;
        }
    }
}"}

